function hexPts(cx, cy, r) {
  var p = [];
  for (var i = 0; i < 6; i++) {
    var a = Math.PI / 3 * i;
    p.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
  }
  return p;
}
/* p0 = right vertex, p1 = lower-right, p2 = lower-left, p3 = left,
   p4 = upper-left, p5 = upper-right */
function ring(g, cx, cy, r, dbEdges) {
  var p = hexPts(cx, cy, r);
  g.polygon(p.map(function (q) { return q.join(','); }).join(' '))
    .fill('none').stroke({ color: INK, width: 1.6, linejoin: 'round' });
  (dbEdges || [0, 2, 4]).forEach(function (e) {
    var a = p[e], b = p[(e + 1) % 6];
    var ix = cx + (a[0] - cx) * 0.68, iy = cy + (a[1] - cy) * 0.68;
    var jx = cx + (b[0] - cx) * 0.68, jy = cy + (b[1] - cy) * 0.68;
    g.line(ix, iy, jx, jy).stroke({ color: INK, width: 1.2 });
  });
  return p;
}
